                    $field .= '"';
                    $i++;
                } else {
                    $quoted = 0;
                    $after_quote = 1;
                }
            } else {
                $field .= $char;
            }
        } elsif ($after_quote) {
            if ($char eq ',') {
                push @fields, $field;
                $field = '';
                $after_quote = 0;
                $at_start = 1;
            } else {
                die "merge: malformed CSV at $where: unexpected character after closing quote\n";
            }
