            if (!$at_start) {
                die "merge: malformed CSV at $where: quote in unquoted field\n";
            }
            $quoted = 1;
            $at_start = 0;
        } else {
            $field .= $char;
            $at_start = 0;
        }
    }

    die "merge: malformed CSV at $where: unterminated quoted field\n" if $quoted;
    push @fields, $field;
    return @fields;
}

sub signature {
    return join('', map { length($_) . ':' . $_ } @_);
}

sub consume_source {
    my ($fh, $source) = @_;
    my $line_number = 0;
    my $saw_header = 0;

    while (defined(my $line = <$fh>)) {
        $line_number++;
        $line =~ s/\r?\n$//;
        next if $line eq '';
        my $where = "$source:$line_number";
        my @fields = csv_fields($line, $where);

        if (!$saw_header) {
            $saw_header = 1;
