    foreach my $source (@ARGV) {
        if ($source eq '-') {
            consume_source(\*STDIN, '<stdin>');
            next;
        }
        open(my $fh, '<', $source)
            or die "merge: cannot open $source: $!\n";
        consume_source($fh, $source);
        close($fh)
            or die "merge: cannot close $source: $!\n";
    }
} else {
    consume_source(\*STDIN, '<stdin>');
}

die "merge: no input header\n" unless defined $published_header;

@records = sort {
    if ($a->{negative} != $b->{negative}) {
        $a->{negative} ? -1 : 1;
    } elsif ($a->{negative}) {
        length($b->{magnitude}) <=> length($a->{magnitude})
