    } else {
        length($a->{magnitude}) <=> length($b->{magnitude})
            || $a->{magnitude} cmp $b->{magnitude};
    }
} @records;

umask 022;
my $temporary = "$base/.merged.csv.$$";
sysopen(my $out, $temporary, O_WRONLY | O_CREAT | O_EXCL, 0644)
    or die "merge: cannot create temporary output: $!\n";
my $cleanup = 1;
END {
    unlink $temporary if $cleanup && defined $temporary && -e $temporary;
}

print $out $published_header, "\n"
    or die "merge: cannot write temporary output: $!\n";
foreach my $record (@records) {
    print $out $record->{raw}, "\n"
        or die "merge: cannot write temporary output: $!\n";
}
close($out)
    or die "merge: cannot close temporary output: $!\n";
rename($temporary, $output)
    or die "merge: cannot publish $output: $!\n";
$cleanup = 0;
